    $id("g1-cmd").innerHTML = L.map(function(l){ return '<span class="cl' + (/\\$/.test(l) && l.charAt(0) === " " ? " cont" : "") + '">' + esc(l).replace(/(-r )/g, '<span class="op">$1</span>').replace(/(\S+:=)/g, '<span class="ty">$1</span>') + "</span>"; }).join("");
