/* ---------- sliders: a large thumb that shows its value, ticks at the lecture's own values (TICKS, set by the frames) ---------- */
function rangeText(inp){ var v = +inp.value, st = inp.step, d = st === "any" ? (Math.abs(+inp.max - +inp.min) <= 2 ? 3 : 2) :
  Math.max(0, ((st.split(".")[1] || "").length)); return f(v, d); }
document.querySelectorAll('.l12w input[type="range"]').forEach(function(inp){
  var w = document.createElement("span"); w.className = "rng"; inp.parentNode.insertBefore(w, inp); w.appendChild(inp);
  var rv = document.createElement("span"); rv.className = "rv"; rv.setAttribute("aria-hidden", "true"); w.appendChild(rv);
  var lo = +inp.min, hi = +inp.max, TW = 78;
  function place(){ TW = rv.offsetWidth || TW; var W = inp.offsetWidth || parseFloat(getComputedStyle(inp).width) || 320, k = (+inp.value - lo) / (hi - lo);
    rv.style.left = (k * (W - TW)) + "px"; rv.textContent = rangeText(inp);
    w.querySelectorAll(".tk").forEach(function(t){ t.style.left = (TW / 2 + (+t.title - lo) / (hi - lo) * (W - TW)) + "px"; }); }
  if (window.ResizeObserver) new ResizeObserver(function(){ place(); }).observe(inp);
  (TICKS[inp.id] || []).forEach(function(v){ var t = document.createElement("span"); t.className = "tk"; t.title = String(v);
    var W = inp.offsetWidth || 320; t.style.left = (TW / 2 + (v - lo) / (hi - lo) * (W - TW)) + "px"; w.appendChild(t); });
  /* a value set by a button or a script moves the thumb's label too */
  var desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value");
  Object.defineProperty(inp, "value", {get:function(){ return desc.get.call(this); }, set:function(v){ desc.set.call(this, v); place(); }, configurable:true});
  inp.addEventListener("input", place);
  inp.addEventListener("pointerdown", function(){ w.classList.add("held"); });
  inp.addEventListener("pointerup", function(){ w.classList.remove("held"); });
  place();
});


/* ---------- live values: when a slider or a frame's button changes the slide's text, the parts that changed get the
   class live-val (drawn in --live). The text is read just before the control's own handler runs (capture phase) and
   compared just after. Elements are matched by their position in the tree, so a list or a formula rebuilt with new
   numbers marks only what changed; the marked positions are kept and marked again after every rebuild. Figures (svg)
   are left out. ---------- */
(function(){
  var SKIP = { SVG:1, SCRIPT:1, STYLE:1, BUTTON:1, INPUT:1 };
  function walk(e, path, out){ var k = 0;
    for (var c = e.firstElementChild; c; c = c.nextElementSibling, k++){
      if (SKIP[c.tagName.toUpperCase()] || (c.classList && (c.classList.contains("try") || c.classList.contains("rng")))) continue;
      var p = path + "/" + k; out[p] = {el:c, txt:c.textContent}; walk(c, p, out); }
    return out; }
  function mark(fr, before){
    var after = walk(fr, "", {}), live = fr._live || (fr._live = {}), changed = [];
    Object.keys(after).forEach(function(p){ if (before[p] && before[p].txt !== after[p].txt) changed.push(p); });
    changed.forEach(function(p){ if (!changed.some(function(q){ return q !== p && q.indexOf(p + "/") === 0; })) live[p] = 1; });
    Object.keys(live).forEach(function(p){ if (after[p]) after[p].el.classList.add("live-val"); }); }
  function watch(ev){ var t = ev.target; if (!t || !t.closest) return;
    var ctl = t.closest('input[type="range"], button'); if (!ctl) return;
    var fr = ctl.closest(".l12w"); if (!fr) return;
    var before = walk(fr, "", {}); setTimeout(function(){ mark(fr, before); }, 60); }
  document.addEventListener("input", watch, true);
  document.addEventListener("click", watch, true);
})();
